// WebAuthn / passkey browser plumbing (DOCB-13745).
//
// The auth service produces options via py_webauthn's options_to_json (challenge,
// user.id, credential ids as base64url STRINGS) and expects the ceremony result
// back with the same base64url encoding. The browser's navigator.credentials API
// instead speaks ArrayBuffers, so these helpers translate both directions. Kept
// dependency-free (no @simplewebauthn/browser) — it is ~two encoders plus two
// thin ceremony wrappers.

function base64urlToBuffer(value: string): ArrayBuffer {
  const base64 = value.replace(/-/g, '+').replace(/_/g, '/');
  const padded = base64.padEnd(base64.length + ((4 - (base64.length % 4)) % 4), '=');
  const binary = atob(padded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

function bufferToBase64url(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export function isWebAuthnSupported(): boolean {
  return (
    typeof window !== 'undefined' &&
    typeof window.PublicKeyCredential !== 'undefined' &&
    typeof navigator !== 'undefined' &&
    !!navigator.credentials
  );
}

 
function prepareCreationOptions(options: any): PublicKeyCredentialCreationOptions {
  return {
    ...options,
    challenge: base64urlToBuffer(options.challenge),
    user: { ...options.user, id: base64urlToBuffer(options.user.id) },
    excludeCredentials: (options.excludeCredentials || []).map((c: any) => ({
      ...c,
      id: base64urlToBuffer(c.id),
    })),
  };
}

function prepareRequestOptions(options: any): PublicKeyCredentialRequestOptions {
  return {
    ...options,
    challenge: base64urlToBuffer(options.challenge),
    allowCredentials: (options.allowCredentials || []).map((c: any) => ({
      ...c,
      id: base64urlToBuffer(c.id),
    })),
  };
}

function serializeRegistration(credential: PublicKeyCredential): any {
  const response = credential.response as AuthenticatorAttestationResponse;
  return {
    id: credential.id,
    rawId: bufferToBase64url(credential.rawId),
    type: credential.type,
    response: {
      attestationObject: bufferToBase64url(response.attestationObject),
      clientDataJSON: bufferToBase64url(response.clientDataJSON),
      transports:
        typeof response.getTransports === 'function' ? response.getTransports() : [],
    },
    clientExtensionResults: credential.getClientExtensionResults(),
    authenticatorAttachment: (credential as any).authenticatorAttachment ?? null,
  };
}

function serializeAuthentication(credential: PublicKeyCredential): any {
  const response = credential.response as AuthenticatorAssertionResponse;
  return {
    id: credential.id,
    rawId: bufferToBase64url(credential.rawId),
    type: credential.type,
    response: {
      authenticatorData: bufferToBase64url(response.authenticatorData),
      clientDataJSON: bufferToBase64url(response.clientDataJSON),
      signature: bufferToBase64url(response.signature),
      userHandle: response.userHandle ? bufferToBase64url(response.userHandle) : null,
    },
    clientExtensionResults: credential.getClientExtensionResults(),
    authenticatorAttachment: (credential as any).authenticatorAttachment ?? null,
  };
}

// Turn a raw WebAuthn DOMException into a friendly, translatable error. The
// browser's own messages ("The operation either timed out or was not allowed.
// See: https://www.w3.org/TR/webauthn-2/…") are noise for end users — carry an
// i18n key on `.code` and a plain-English fallback on `.message`.
export class PasskeyError extends Error {
  code: string;
  constructor(code: string, message: string) {
    super(message);
    this.name = 'PasskeyError';
    this.code = code;
  }
}

function mapWebAuthnError(err: unknown, ceremony: 'register' | 'auth'): PasskeyError {
  const name = (err as DOMException)?.name || '';
  switch (name) {
    case 'NotAllowedError':
    case 'AbortError':
      return new PasskeyError(
        'mfa_passkey_error_not_allowed',
        'The passkey prompt was dismissed or timed out. Please try again.',
      );
    case 'InvalidStateError':
      return ceremony === 'register'
        ? new PasskeyError(
            'mfa_passkey_error_already_registered',
            'This device already has a passkey for your account.',
          )
        : new PasskeyError(
            'mfa_passkey_error_no_credential',
            'No passkey for this account was found on this device.',
          );
    case 'NotSupportedError':
      return new PasskeyError(
        'mfa_passkey_error_not_supported',
        "This device doesn't support passkeys.",
      );
    case 'SecurityError':
      return new PasskeyError(
        'mfa_passkey_error_security',
        'Passkeys are not available on this address.',
      );
    default:
      return new PasskeyError(
        'mfa_passkey_error_generic',
        'Passkey action failed. Please try again.',
      );
  }
}

// Run the create() ceremony against server options; return the JSON the auth
// service's /webauthn/register/complete expects.
export async function performRegistration(optionsJSON: any): Promise<any> {
  const publicKey = prepareCreationOptions(optionsJSON);
  let credential: PublicKeyCredential | null;
  try {
    credential = (await navigator.credentials.create({
      publicKey,
    })) as PublicKeyCredential | null;
  } catch (err) {
    throw mapWebAuthnError(err, 'register');
  }
  if (!credential)
    throw new PasskeyError('mfa_passkey_error_not_allowed', 'Passkey registration was cancelled');
  return serializeRegistration(credential);
}

// Run the get() ceremony; return the JSON /webauthn/verify expects.
export async function performAuthentication(optionsJSON: any): Promise<any> {
  const publicKey = prepareRequestOptions(optionsJSON);
  let credential: PublicKeyCredential | null;
  try {
    credential = (await navigator.credentials.get({
      publicKey,
    })) as PublicKeyCredential | null;
  } catch (err) {
    throw mapWebAuthnError(err, 'auth');
  }
  if (!credential)
    throw new PasskeyError('mfa_passkey_error_not_allowed', 'Passkey verification was cancelled');
  return serializeAuthentication(credential);
}
 
